public class Main {
    static boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] numbers = {17, 18, 19, 20, 21};
        for (int n : numbers) {
            System.out.println(n + (isPrime(n) ? " is prime" : " is not prime"));
        }
    }
}
